import{z as s,x as o,o as i,c as u,q as l,j as A,D as r,d as e,s as n,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"谨慎与 Kimball","description":"","frontmatter":{"title":"谨慎与 Kimball","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/prudence-kimball.md","filePath":"econ/prudence-kimball.md","lastUpdated":1791063341000}'),m={name:"econ/prudence-kimball.md"};function B(d,a,c,_,C,g){const t=o("Mermaid");return i(),u("div",null,[a[2]||(a[2]=l('<h1 id="谨慎与-kimball" tabindex="-1">谨慎与 Kimball <a class="header-anchor" href="#谨慎与-kimball" aria-label="Permalink to &quot;谨慎与 Kimball&quot;">​</a></h1><div class="epigraph"><p>风险厌恶管的是「讨厌噪声」；预防性储蓄问的是「噪声是否让人更想攒钱」。后者要看三阶导，不是更凹。</p><footer>—— 据 Kimball, Precautionary Saving in the Small and in the Large, Econometrica, 1990 整理</footer></div><p><a href="/econ/cara-crra">上一课</a>钉了 \\(r_A\\) 的形状：CARA、CRRA、DARA。本课不重解那些微分方程，也不把 Pratt 溢价再推一遍。缺口是：\\(r_A=-u&#39;&#39;/u&#39;\\) 只动到二阶。后课随机收入、欧拉方程里的「不确定性提高储蓄」，需要 \\(u&#39;&#39;&#39;\\) 的符号。Kimball 把绝对谨慎 \\(\\pi=-u&#39;&#39;&#39;/u&#39;&#39;\\) 收成与 \\(r_A\\) 平行的一套局部理论；凹性不够。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两期、第二期收入带零均值噪声 \\(\\tilde\\varepsilon\\)。确定情形的欧拉是 \\(u&#39;(c_0)=\\beta(1+r)u&#39;(c_1)\\)。噪声进来之后，若仍用同一 \\(c_1\\) 的均值去算，等式一般不再成立。缺口是：何时 \\(\\mathbb{E}u&#39;(w+\\tilde\\varepsilon)\\gt u&#39;(w)\\)，从而使当期消费下降、储蓄上升？Jensen 要求 \\(u&#39;\\) <strong>凸</strong>，即 \\(u&#39;&#39;&#39;\\gt 0\\)。这叫谨慎（prudence），与 \\(u&#39;&#39;\\lt 0\\) 的风险厌恶不是同一句话。</p><p>Kimball 定义绝对谨慎 \\(\\pi(w)=-u&#39;&#39;&#39;(w)/u&#39;&#39;(w)\\)，相对谨慎 \\(w\\pi(w)\\)。局部上，预防性溢价（为了消除噪声愿意压低多少确定财富）由 \\(\\pi\\) 扮演 Pratt 公式里 \\(r_A\\) 的角色。本课只钉这一阶对应，不把「小风险」与「大风险」的全部定理重写。</p><p><span class="marginnote">术语翻译：谨慎（prudence）就是「坏状态里一块钱更值钱」——噪声把消费推到更穷的状态，那里边际效用更高，于是你宁可先攒一笔。它与「讨厌噪声」（风险厌恶）是两回事：一个看 \\(u&#39;&#39;\\) 的凹，一个看 \\(u&#39;&#39;&#39;\\) 的凸。</span></p><h3 id="更凹不必更谨慎" tabindex="-1">更凹不必更谨慎 <a class="header-anchor" href="#更凹不必更谨慎" aria-label="Permalink to &quot;更凹不必更谨慎&quot;">​</a></h3><p>\\(r_A\\) 更大是更厌恶二阶风险。\\(\\pi\\) 更大是对均值保留展形更想预防性储蓄。可以构造 \\(u\\)：\\(r_A\\) 处处更大但 \\(\\pi\\) 更小。CARA：\\(u=-e^{-\\alpha w}\\)，\\(\\pi=\\alpha=r_A\\)，谨慎与绝对厌恶同值。CRRA：相对谨慎 \\(=\\gamma+1\\)，比相对厌恶多 \\(1\\)。不要把「幂效用很厌恶」读成「预防性储蓄很大」而不报 \\(\\gamma+1\\)。</p><p><span class="marginnote">三次以上的符号还有节制（temperance，\\(u&#39;&#39;&#39;&#39;\\) 的符号），背景风险下一课才用。本课停在三阶与储蓄。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定两次以上可微、严格递增凹的 \\(u\\)，直接读 \\(u&#39;&#39;&#39;\\) 是否为正，再算 \\(\\pi\\)。两期问题把第二期资源写成 \\(w_1+\\tilde\\varepsilon\\)，比较有噪声与无噪声的 \\(c_0\\)。\\(u&#39;&#39;&#39;\\gt 0\\) 则有噪声时 \\(c_0\\) 更低。公平保险已经由凹性给出全额投保；预防性储蓄是<strong>未保险</strong>的未来风险挤占当期消费，对象不同。</p><p>CARA 加独立噪声：绝对预防性储蓄与财富无关，和上一课绝对风险需求对 \\(w\\) 无弹性同一机制。CRRA 下预防性项与财富成比例。DARA 不蕴含谨慎，但常用的 CRRA、CARA 都谨慎。二次效用 \\(u&#39;&#39;&#39;=0\\)，没有预防性储蓄——又一条把它排除出主干的理由。</p><p><span class="marginnote">常见误区：初学者容易以为「越厌恶风险就越会多存钱」。实际上二次效用一分预防性储蓄都没有；CRRA 的相对谨慎是 \\(\\gamma+1\\)，比相对厌恶 \\(\\gamma\\) 恰好多 1。谈预防性动机要报谨慎指数，不是把厌恶指数改个名。</span></p>',14)),(i(),A(p,null,{default:r(()=>[n(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20RA%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9Ar_A%20%3D%20-u''%2Fu'%22%5D%20--%3E%20GAP%5B%22%E5%82%A8%E8%93%84%E8%BF%98%E8%A6%81%20u'''%22%5D%0A%20%20GAP%20--%3E%20PRU%5B%22%E8%B0%A8%E6%85%8E%EF%BC%9A%CF%80%20%3D%20-u'''%2Fu''%22%5D%0A%20%20PRU%20--%3E%20PS%5B%22u'''%20%3E%200%EF%BC%9A%E9%A2%84%E9%98%B2%E6%80%A7%E5%82%A8%E8%93%84%22%5D%0A%20%20PRU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%83%8C%E6%99%AF%E9%A3%8E%E9%99%A9%E6%94%B9%E6%9C%89%E6%95%88%20r_A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课不估计 \\(\\pi\\)。宏观欧拉若写「不确定提高储蓄」，是在用谨慎，不是把 \\(r_A\\) 改名。也不把 \\(\\pi\\) 写成限价簿上的安全垫。多期缓冲存货、习惯形成会把「预防性」与其他储蓄动机混在一起，本课的两期可分 \\(u\\) 是最小工作例子。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("\\(u'\\) 凸的机制是：同样的均值，展形把质量推到更穷的状态，那里边际效用更高，期望 \\(u'\\) 被拉起。为了压回欧拉，必须提高 \\(c_1\\) 的均值，即先存一笔。这与 Pratt 溢价不同：溢价比较的是「接受风险要多少确定补偿」，预防性比较的是「跨期如何挪动」。展形伤害凹 \\(u\\)（SOSD）；谨慎额外决定"),E("strong",null,"何时"),e("用储蓄去缓冲。")],-1)),(i(),A(p,null,{default:r(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20NOISE%5B%22%E7%AC%AC%E4%BA%8C%E6%9C%9F%E6%94%B6%E5%85%A5%E5%8A%A0%E9%9B%B6%E5%9D%87%E5%80%BC%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20BAD%5B%22%E5%9D%8F%E7%8A%B6%E6%80%81%3A%20%E6%B6%88%E8%B4%B9%E6%9B%B4%E4%BD%8E%2C%20%E8%BE%B9%E9%99%85%E6%95%88%E7%94%A8%E6%9B%B4%E9%AB%98%22%5D%0A%20%20NOISE%20--%3E%20GOOD%5B%22%E5%A5%BD%E7%8A%B6%E6%80%81%3A%20%E6%B6%88%E8%B4%B9%E6%9B%B4%E9%AB%98%2C%20%E8%BE%B9%E9%99%85%E6%95%88%E7%94%A8%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20BAD%20--%3E%20EU%5B%22E%20u'(c_1)%20%E8%A2%AB%E5%9D%8F%E7%8A%B6%E6%80%81%E6%8B%89%E9%AB%98%22%5D%0A%20%20GOOD%20--%3E%20EU%0A%20%20EU%20--%3E%20GAP%5B%22%E6%AC%A7%E6%8B%89%E5%8F%B3%E8%BE%B9%E5%8F%98%E5%A4%A7%2C%20%E7%AD%89%E5%BC%8F%E5%A4%B1%E8%A1%A1%22%5D%0A%20%20GAP%20--%3E%20SAVE%5B%22c_0%20%E9%99%8D%201%20%E5%85%83%E8%BD%AC%E5%85%A5%E5%82%A8%E8%93%84%22%5D%0A%20%20SAVE%20--%3E%20FIX%5B%22c_1%20%E5%9D%87%E5%80%BC%E6%8A%AC%E9%AB%98%2C%20E%20u'%20%E5%9B%9E%E8%90%BD%2C%20%E7%AD%89%E5%BC%8F%E9%87%8D%E6%96%B0%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>与形状课的接口：CRRA 的 \\(\\gamma\\) 同时是相对厌恶和跨期替代的倒数——若宏观把同一幂函数兼用在时间和风险上。本课只谈风险侧的三阶；\\(\\gamma+1\\) 是相对谨慎，不是跨期替代。</p><p><span class="marginnote">Kimball 1990 的标题「in the small and in the large」对应 Pratt：局部用 \\(\\pi\\)，全局用谨慎函数的比较。引用不要写成另一条风险厌恶指数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多期、习惯、借贷约束会让「预防性」混进流动性需求。本课只在两期、可自由借贷、单一未保风险上定义。模糊没有 \\(u&#39;&#39;&#39;\\) 可算。不完全市场下劳动收入不可保，预防性与背景风险缠在一起——下一课把第二项打开。</p><p>局部预防性溢价（Kimball 的 \\(\\psi\\)）满足 \\(\\psi\\approx\\tfrac12\\pi\\sigma^2\\)，与 Pratt 的 \\(\\pi_{\\mathrm{Pratt}}\\approx\\tfrac12 r_A\\sigma^2\\) 同形，只是把 \\(-u&#39;&#39;/u&#39;\\) 换成 \\(-u&#39;&#39;&#39;/u&#39;&#39;\\)。全局比较：若 \\(\\pi^1(w)\\ge\\pi^2(w)\\) 处处成立，则同一噪声下 \\(1\\) 比 \\(2\\) 存得更多。本课要这条平行，不把大风险定理的全部不等式写完。</p><p><span class="marginnote">数字实例：设 \\(\\pi=3\\)、噪声标准差 \\(\\sigma=0.2\\)（财富的两成），则 \\(\\sigma^2=0.04\\)，\\(\\psi\\approx\\tfrac12\\times3\\times0.04=0.06\\)——为消除这笔风险，你愿意放弃相当于财富 \\(6\\%\\) 的确定数量。注意溢价比 \\(\\sigma\\) 涨得快：噪声标准差翻倍，溢价变四倍。</span></p><p>也不要把 \\(u&#39;&#39;&#39;\\gt 0\\) 写成「喜欢正偏度」的完整理论；三阶占优会把这句话收成分布偏序，本课只钉储蓄的一阶条件。背景风险下一课会问：同一份 \\(u&#39;&#39;&#39;\\)，如何改变对<strong>另一份</strong>可保风险的有效 \\(r_A\\)——那不是储蓄欧拉，不要在本课提前焊上。</p><p>后课默认：谈到预防性储蓄，先查 \\(u&#39;&#39;&#39;\\gt 0\\) 与 \\(\\pi\\)；CARA/CRRA 工作函数都谨慎。风险厌恶指数不够写这一项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>风险厌恶是 \\(u&#39;&#39;\\lt 0\\)；预防性储蓄需要 \\(u&#39;\\) 凸，即 \\(u&#39;&#39;&#39;\\gt 0\\)。</li><li>绝对谨慎 \\(\\pi=-u&#39;&#39;&#39;/u&#39;&#39;\\) 在局部扮演 Pratt 公式里 \\(r_A\\) 的角色。</li><li>CARA 则 \\(\\pi=r_A\\)；CRRA 的相对谨慎是 \\(\\gamma+1\\)。</li><li>二次效用无预防性；更凹不必更谨慎。</li><li>出处：Kimball, <em>Econometrica</em>, 1990。</li></ul>',10))])}const b=s(m,[["render",B]]);export{D as __pageData,b as default};
